"""Render audit trail and the gates around image generation. Images are generated by the harness (Claude Code /
OpenCode / Codex) with whatever image tool it exposes; nothing here calls a model.

  reference_images()  the ordered list of images to attach (the prompt says what each one is)
  preflight()         BEFORE generating: metadata valid and current, shot is a planned mockup, prompt exists,
                      references fit the fidelity mode, attempt budget not used up
  register()          AFTER generating: copy images into renders/<shot>/vN-i.<ext> + vN.json (prompt, engine,
                      refs, attempt number, metadata hash)

One `register` call = one attempt. The budget is `generation.max_attempts` in the resolved design; going past
it needs the user's go-ahead, recorded with `preflight --extra-attempt "<what they said>"`.
"""
from __future__ import annotations

import re
import shutil
from pathlib import Path

from . import metadata, paths
from .paths import Product, die

SUBJECT_REF_MODES = ("exact", "likeness")


def _next_version(shot_dir: Path) -> int:
    vs = [int(m.group(1)) for f in shot_dir.glob("v*-*.*") if (m := re.match(r"v(\d+)-", f.name))]
    return max(vs, default=0) + 1


def shot_slug(shot: str) -> str:
    return paths.slugify(shot)


def shot_dir(prod: Product, shot: str) -> Path:
    return prod.work / "renders" / shot_slug(shot)


def reference_images(prod: Product, *, only_primary=False, no_product_refs=False, extra=None, with_style_refs=False) -> list[Path]:
    """Order: primary subject photo, other subject photos, extra --ref files, then refs/ (style refs).
    A concept job (no subject photo) has only --ref files and refs/."""
    if no_product_refs or not prod.images:
        refs = []
    else:
        refs = [prod.primary_image] if only_primary else list(prod.images)
    refs += [paths.p(r) for r in (extra or [])]
    if with_style_refs:
        refs += prod.style_refs
    for r in refs:
        if not r.exists():
            die(f"reference image not found: {r}")
    return refs


def _planned(meta: dict, shot: str) -> dict:
    m = metadata.mockup(meta, shot)
    if not m:
        die(f"shot '{shot_slug(shot)}' is not a planned mockup (planned: {', '.join(x['name'] for x in meta['design']['mockups'])}). "
            "Add it to the `mockups` of the session design layer (output/<id>/design/session.json), then re-run "
            "`studio.py design` and `studio.py metadata`.")
    return m


def budget(prod: Product, meta: dict, shot: str) -> dict:
    """Attempts used / allowed for a shot. Extra attempts are user approvals recorded by preflight."""
    d = shot_dir(prod, shot)
    extra = paths.read_json(d / "attempts.json", [])
    used = _next_version(d) - 1 if d.exists() else 0
    allowed = meta["design"]["generation"]["max_attempts"] + len(extra)
    return {"used": used, "allowed": allowed, "left": max(0, allowed - used), "extra_approved": extra}


def _missing_subject_ref(prod: Product, meta: dict, refs: list[Path]) -> str | None:
    mode = meta["generation_constraints"]["fidelity"]
    if mode in SUBJECT_REF_MODES and not any(r in prod.images for r in refs):
        return f"fidelity '{mode}' needs at least one subject photo as a reference, but none is attached"
    return None


def preflight(prod: Product, shot: str, refs: list[Path], extra_attempt: str | None = None) -> dict:
    """Everything that must hold before one generation of `shot`; returns what to pass to the image tool."""
    meta = metadata.require_current(prod)
    m = _planned(meta, shot)
    prompt = prod.work / "creative" / "prompts" / f"{m['name']}.md"
    if not prompt.exists() or not prompt.read_text(encoding="utf-8").strip():
        die(f"no prompt for this shot: write {paths.rel(prompt)} first (product-creative).")
    problem = _missing_subject_ref(prod, meta, refs)
    if problem:
        die(f"{problem}. Drop --no-product-refs for this shot.")
    d = shot_dir(prod, shot)
    b = budget(prod, meta, shot)
    if extra_attempt and b["left"] == 0:  # an approval only counts once the budget is really used up
        paths.write_json(d / "attempts.json", [*b["extra_approved"], {"reason": extra_attempt, "at": paths.now()}])
        b = budget(prod, meta, shot)
    if b["left"] == 0:
        die(f"attempt budget for '{m['name']}' is used up ({b['used']} of {b['allowed']}). Stop and report the problem to "
            "the user; if they want another try, re-run preflight with --extra-attempt \"<their go-ahead>\".")
    paths.record(prod, f"preflight:{m['name']}", attempt=b["used"] + 1, allowed=b["allowed"])
    return {
        "shot": m["name"], "type": m["type"], "attempt": b["used"] + 1, "attempts_allowed": b["allowed"],
        "variations": m["variations"], "output": m["style"]["output"], "prompt_file": paths.rel(prompt),
        "reference_images": [str(r) for r in refs], "fidelity": meta["generation_constraints"]["fidelity"],
        "must_avoid": m["must_avoid"], "identity_constraints": meta["generation_constraints"]["identity_constraints"],
        "text_policy": meta["generation_constraints"]["text_policy"],
        "note": "attach the reference images in this order; pass the whole prompt file; then `register` every image",
    }


def register(prod: Product, shot: str, images: list[Path], prompt: str, engine: str, refs: list[Path],
             model: str | None = None, params: dict | None = None, notes: str | None = None) -> dict:
    """Log images produced by the harness's image tool into the audit trail (one attempt, n variations)."""
    meta = metadata.require_current(prod)
    m = _planned(meta, shot)
    for image in images:
        if not image.exists():
            die(f"image not found: {image}")
        if image.suffix.lower() not in paths.IMAGE_EXTS:
            die(f"not an image ({', '.join(sorted(paths.IMAGE_EXTS))}): {image}")
    d = shot_dir(prod, shot)
    d.mkdir(parents=True, exist_ok=True)
    version = _next_version(d)
    b = budget(prod, meta, shot)
    files = []
    for i, image in enumerate(images, 1):
        out = d / f"v{version}-{i}{image.suffix.lower()}"
        shutil.copy2(image, out)
        files.append(paths.rel(out))
    record = {
        "product_id": prod.id, "shot": m["name"], "version": version, "attempt": version,
        "attempts_allowed": b["allowed"], "over_budget": version > b["allowed"],
        "engine": engine, "model": model, "params": params or {}, "planned_output": m["style"]["output"],
        "references": [paths.rel(r) for r in refs], "reference_problem": _missing_subject_ref(prod, meta, refs),
        "prompt": prompt, "metadata_sha256": paths.sha256_file(metadata.path(prod)),
        "originals": [str(i) for i in images], "files": files, "notes": notes, "created_at": paths.now(),
    }
    paths.write_json(d / f"v{version}.json", record)
    paths.record(prod, f"render:{m['name']}", version=version, files=len(files), engine=engine,
                 over_budget=record["over_budget"])
    left = b["allowed"] - version
    return {**record, "attempts_left": max(0, left),
            "next": "QA these images (`qa-mark`)" + ("" if left > 0 else "; no attempts left — a failed QA goes to the user")}


def meta_for(render_path: Path) -> dict | None:
    m = re.match(r"(v\d+)-\d+", render_path.stem)
    if not m:
        return None
    return paths.read_json(render_path.parent / f"{m.group(1)}.json")
